const BLOG_CATEGORIES = ["Sofas & Sofa Beds", "Wardrobes", "Beds & Mattresses", "Buying Guides", "Delivery & Care", "Seasonal & Room Ideas"];

function getArticleByHandle(handle) {
  return ARTICLES.find(a => a.handle === handle);
}

function articlesByCategory(cat) {
  if (!cat || cat === "All") return ARTICLES;
  return ARTICLES.filter(a => a.category === cat);
}

function latestArticles(n) {
  return ARTICLES.slice()
    .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt))
    .slice(0, n);
}

function relatedArticlesPick(article, count) {
  const pool = ARTICLES.filter(a => a.handle !== article.handle && a.category === article.category);
  const chosen = pool.length >= count ? pool : ARTICLES.filter(a => a.handle !== article.handle);
  const seed = hashSeed(article.handle);
  const shuffled = chosen.slice().sort((a, b) => hashSeed(a.handle + seed) - hashSeed(b.handle + seed));
  return shuffled.slice(0, count);
}

// Category -> best-fit shop.html query string, used for the closing CTA on an article page.
const CATEGORY_SHOP_LINK = {
  "Sofas & Sofa Beds": "shop.html?cat=Sofa%20Beds",
  "Wardrobes": "shop.html?cat=Wardrobes",
  "Beds & Mattresses": "shop.html?cat=Beds%20%26%20Mattresses",
  "Buying Guides": "shop.html",
  "Delivery & Care": "shop.html",
  "Seasonal & Room Ideas": "shop.html",
};

function categoryShopLink(category) {
  return CATEGORY_SHOP_LINK[category] || "shop.html";
}

// Prefer a tag-based match (more specific — e.g. "corner sofas" vs the
// broader "Sofas & Sofa Beds" bucket) before falling back to the category map.
function articleShopLink(article) {
  const tags = (article.tags || []).map(t => t.toLowerCase());
  if (tags.includes("sofa beds")) return "shop.html?cat=Sofa%20Beds";
  if (tags.includes("corner sofas")) return "shop.html?cat=Corner%20Sofas";
  if (tags.includes("sofas") || tags.includes("chesterfield") || tags.includes("fabric")) return "shop.html?cat=Sofas";
  if (tags.some(t => t.includes("wardrobe"))) return "shop.html?cat=Wardrobes";
  if (tags.includes("beds") || tags.includes("mattresses") || tags.includes("divan beds") || tags.includes("bunk beds") || tags.includes("sleep")) return "shop.html?cat=Beds%20%26%20Mattresses";
  if (tags.includes("garden furniture") || tags.includes("outdoor")) return "shop.html?cat=Outdoor%20Furniture";
  if (tags.includes("dining")) return "shop.html?cat=Dining%20Tables";
  return categoryShopLink(article.category);
}
